∀ {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {α : ℝ} {p : Fin k → ℝ} {u : Breakdown.Space → Breakdown.Space}
  {G : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {P : Breakdown.Space → Breakdown.Space} {κ : Fin k → ℝ},
  d.IsHeldSolution α p u G H P κ →
    ∃ Q,
      Breakdown.SteadyCert.IsGradientField Q ∧
        ∀ᵐ (y : Breakdown.Space), d.fullField α p u G H P κ y + (G y) (u y) + d.defect α p y + Q y = 0

