∀ {α a : ℝ} {m : ℕ} {F v : Breakdown.Space → Breakdown.Space}
  {G : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {P : Breakdown.Space → Breakdown.Space} {second : Breakdown.SteadyCert.IsSecondOrderField m v G H}
  {power : Breakdown.SteadyCert.IsWeakFractionalPower α v P}
  {drift : MeasureTheory.MemLp (Breakdown.SteadyCert.driftField α a v G) 2 MeasureTheory.volume}
  {eq : ∀ᵐ (y : Breakdown.Space), Breakdown.SteadyCert.driftField α a v G y + P y = F y}
  {v_1 : Breakdown.Space → Breakdown.Space} {G_1 : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H_1 : Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {P_1 : Breakdown.Space → Breakdown.Space} {second_1 : Breakdown.SteadyCert.IsSecondOrderField m v_1 G_1 H_1}
  {power_1 : Breakdown.SteadyCert.IsWeakFractionalPower α v_1 P_1}
  {drift_1 : MeasureTheory.MemLp (Breakdown.SteadyCert.driftField α a v_1 G_1) 2 MeasureTheory.volume}
  {eq_1 : ∀ᵐ (y : Breakdown.Space), Breakdown.SteadyCert.driftField α a v_1 G_1 y + P_1 y = F y},
  { v := v, G := G, H := H, P := P, second := second, power := power, drift := drift, eq := eq } =
      { v := v_1, G := G_1, H := H_1, P := P_1, second := second_1, power := power_1, drift := drift_1, eq := eq_1 } →
    v = v_1 ∧ G = G_1 ∧ H = H_1 ∧ P = P_1

∀ (α a μ : ℝ) {f : Breakdown.Space → Breakdown.Space},
  Differentiable ℝ f →
    ∀ (y : Breakdown.Space),
      Breakdown.FracCert.driftAdjoint α a (Breakdown.FracCert.simAdj α a μ f) y =
        have R := Breakdown.axialRotation (-(a * Real.log μ));
        have w := (Breakdown.axialRotation (a * Real.log μ)) y;
        have c := μ ^ (4 * (1 / (2 * α)) - 1);
        have k := μ ^ (1 / (2 * α));
        (1 - 4 * (1 / (2 * α))) • R (c • f (k • w)) - (1 / (2 * α)) • R (c • (fderiv ℝ f (k • w)) (k • w)) -
          a • (R (c • (fderiv ℝ f (k • w)) (k • Breakdown.axialTurn w)) - Breakdown.axialTurn (R (c • f (k • w))))

